import React, { useCallback, useEffect, useState } from "react";
import { Box, Backdrop, CircularProgress } from "@mui/material";
import { Helmet } from "react-helmet";
import TypeToFilterSearch from "components/TypeToFilterSearch";
import ApplicationAssessmentListTable from "./ApplicationCollateralListTable";
import { useParams } from "react-router";
import { useDispatch, useSelector } from "react-redux";
import { useSearchParams } from "react-router-dom";
import ApplicationTitle from "components/application/ApplicationTitle";
import { getAllCollaterals } from "modules/loan-operation/slices/collateralSlice";
import ApplicationCollateralListToolbar from "./ApplicationCollateralListToolbar";
import ApplicationCollateralListContractToolbar from "./ApplicationCollateralListContractToolbar";

const ApplicationCollateralListIndex = () => {
  const { applicationId: application_id, applicationUUId: application_uuid, contractId, path } =
    useParams();

  const dispatch = useDispatch();
  const [params] = useSearchParams();
  const [selectedCollaterals, setSelectedCollaterals] = useState([]);

  const onSelectionChangedCollaterals = useCallback((rows) => {
    setSelectedCollaterals(rows || []);
  }, []);

  const { collaterals, isLoading } = useSelector(
    (state) => state.collaterals
  );


  const fetchApi = useCallback(() => {
    dispatch(
      getAllCollaterals({
        params: {
          ...Object.fromEntries(params),
          application_id,
        },
      })
    );
  }, [application_id, dispatch, params]);

  useEffect(() => {
    fetchApi();
  }, [fetchApi]);

  // useEffect(() => {
  //   dispatch(getApplicationByUuid({ uuid: application_uuid }));
  // }, [application_uuid, dispatch]);

  return (
    <>
      <Helmet>
        <title>Application Collateral List</title>
      </Helmet>
      <Backdrop
        sx={{ color: "#fff", zIndex: (theme) => theme.zIndex.drawer + 1 }}
        open={isLoading}
      >
        <CircularProgress color="inherit" />
      </Backdrop>
      {
        path === "contract" ? (
          <ApplicationCollateralListContractToolbar
            selectedCollaterals={selectedCollaterals}
            applicationId={application_id}
            applicationUUId={application_uuid}
            contractId={contractId}
          />
        ) : (
          <ApplicationCollateralListToolbar
            selectedCollaterals={selectedCollaterals}
            applicationId={application_id}
            applicationUUId={application_uuid}
          />
        )
      }
      <Box
        sx={{
          px: 1,
          display: "flex",
          mb: 1,
          alignItems: "center",
        }}
      >
        <ApplicationTitle
          sx={{ flex: 1, px: 0 }}
          sxTypography={{ m: 0 }}
          title="Application Collateral List"
          application={collaterals[0]?.application}
        />

        <TypeToFilterSearch
          selectProps={{
            options: [],
            defaultValue: [],
          }}
        />
      </Box>

      <Box
        sx={{
          px: 1,
          pb: 1,
        }}
      >
        <ApplicationAssessmentListTable
          onSelectionChangedCollaterals={onSelectionChangedCollaterals}
        />
      </Box>
    </>
  );
};

export default React.memo(ApplicationCollateralListIndex);
